import React, { useState } from 'react';
import { 
  Home, List, BookOpen, Database, Menu, X, ChevronRight 
} from 'lucide-react';
import {
  XAxis, YAxis, CartesianGrid, ResponsiveContainer, LineChart, Line
} from 'recharts';

// --- モックデータ ---
const trendData = [
  { name: '第6号', onePiece: 1.2, jjk: 2.1, mha: 2.8 },
  { name: '第7号', onePiece: 1.8, jjk: 1.5, mha: 3.0 },
  { name: '第8号', onePiece: 1.1, jjk: 2.3, mha: 1.5 },
  { name: '第9号', onePiece: 1.5, jjk: 2.0, mha: 2.2 },
  { name: '第10号', onePiece: 1.0, jjk: 1.8, mha: 2.5 },
];

export default function LineChartFromCSV() {
  // サイドバーの開閉状態を管理
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  // 共通のスタイル定数
  const colors = {
    bg: '#0f172a',
    sidebar: '#1a2235',
    content: '#161d2f',
    accent: '#3b82f6',
    border: '#2d3748',
    textMuted: '#94a3b8'
  };

  return (
    <div style={{ 
      display: 'flex', 
      backgroundColor: colors.bg, 
      minHeight: '100vh', 
      color: 'white', 
      fontFamily: 'sans-serif',
      position: 'relative',
      overflowX: 'hidden'
    }}>

      {/* ハンバーガーメニューボタン（モバイル・デスクトップ共通） */}
      <button 
        onClick={() => setSidebarOpen(!isSidebarOpen)}
        style={{
          position: 'fixed',
          top: '20px',
          left: '20px',
          zIndex: 100,
          backgroundColor: colors.sidebar,
          border: `1px solid ${colors.border}`,
          borderRadius: '4px',
          padding: '8px',
          cursor: 'pointer',
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

      {/* サイドバー（ドロワー形式） */}
      <aside style={{ 
        width: '240px', 
        backgroundColor: colors.sidebar, 
        borderRight: `1px solid ${colors.border}`, 
        paddingTop: '80px',
        position: 'fixed',
        height: '100vh',
        left: isSidebarOpen ? '0' : '-240px',
        transition: 'left 0.3s ease-in-out',
        zIndex: 90,
        boxShadow: isSidebarOpen ? '10px 0 15px rgba(0,0,0,0.3)' : 'none'
      }}>
        <nav>
          {[
            { icon: <Home size={18}/>, label: "ホーム", active: true },
            { icon: <List size={18}/>, label: "号別ランキング" },
            { icon: <BookOpen size={18}/>, label: "作品一覧" },
            { icon: <Database size={18}/>, label: "データ管理" }
          ].map((item, i) => (
            <div key={i} style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              padding: '15px 24px',
              backgroundColor: item.active ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
              borderLeft: item.active ? `4px solid ${colors.accent}` : '4px solid transparent',
              color: item.active ? colors.accent : colors.textMuted,
              cursor: 'pointer'
            }}>
              {item.icon}
              <span style={{ fontSize: '14px', fontWeight: item.active ? 'bold' : 'normal' }}>{item.label}</span>
            </div>
          ))}
        </nav>
      </aside>

      {/* オーバーレイ（サイドバーが開いている時に背景を暗くする） */}
      {isSidebarOpen && (
        <div 
          onClick={() => setSidebarOpen(false)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            zIndex: 80
          }}
        />
      )}

      {/* メインコンテンツ（中央のランキングのみ） */}
      <main style={{ 
        flex: 1, 
        padding: '80px 40px 40px 40px',
        maxWidth: '800px',
        margin: '0 auto',
        transition: 'margin-left 0.3s ease-in-out'
      }}>
        <header style={{ marginBottom: '40px' }}>
          <h2 style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '8px' }}>2026年 第10号</h2>
          <div style={{ width: '60px', height: '4px', backgroundColor: colors.accent }}></div>
        </header>

        {/* ランキングリスト */}
        <section style={{ 
          backgroundColor: colors.content, 
          borderRadius: '12px', 
          padding: '24px',
          border: `1px solid ${colors.border}`,
          marginBottom: '40px'
        }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {['ONE PIECE', '呪術廻戦', '僕のヒーローアカデミア', 'サカモトデイズ', 'アオのハコ'].map((name, i) => (
              <div key={i} style={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'space-between',
                paddingBottom: i === 4 ? '0' : '15px',
                borderBottom: i === 4 ? 'none' : `1px solid ${colors.border}`
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                  <span style={{ fontSize: '24px', fontWeight: 'bold', fontStyle: 'italic', color: i === 0 ? '#fbbf24' : 'white', width: '40px' }}>
                    {i + 1}
                  </span>
                  <span style={{ fontSize: '18px', fontWeight: '500' }}>{name}</span>
                </div>
                <ChevronRight size={18} color={colors.textMuted} />
              </div>
            ))}
          </div>

          <button style={{
            width: '100%', 
            marginTop: '24px',
            padding: '14px', 
            backgroundColor: '#252f48', 
            border: `1px solid ${colors.border}`,
            borderRadius: '8px', 
            color: 'white', 
            cursor: 'pointer', 
            fontWeight: 'bold',
            fontSize: '14px'
          }}>
            全順位を見る
          </button>
        </section>

        {/* トレンドグラフ */}
        <section>
          <h3 style={{ fontSize: '16px', color: colors.textMuted, marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span style={{ width: '4px', height: '16px', backgroundColor: colors.accent }}></span>
            トレンド推移
          </h3>
          <div style={{ 
            height: '250px', 
            backgroundColor: colors.content, 
            padding: '20px', 
            borderRadius: '12px',
            border: `1px solid ${colors.border}`
          }}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={trendData}>
                <CartesianGrid vertical={false} stroke={colors.border} strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{fill: colors.textMuted, fontSize: 12}} axisLine={false} tickLine={false} />
                <YAxis reversed domain={[1, 4]} hide />
                <Line type="monotone" dataKey="onePiece" stroke="#60a5fa" strokeWidth={3} dot={{r: 4, fill: '#fff'}} />
                <Line type="monotone" dataKey="jjk" stroke="#f87171" strokeWidth={2} dot={{r: 3}} />
                <Line type="monotone" dataKey="mha" stroke="#4ade80" strokeWidth={2} dot={{r: 3}} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </section>
      </main>
    </div>
  );
}
